  if(firstActDamage){const n=Number(firstActDamage[1]),target=chosenEnemy||(!targetUid?o.board[0]:undefined);if(target){const targetOwner=(chosenEnemy?owner===0?1:0:owner===0?1:0) as 0|1;const splash=/adjacentes ao alvo/i.test(primaryText)?Number(primaryText.match(/e\s+(\d+)\s+de dano as criaturas adjacentes/i)?.[1]||0):0;deferUnitImpact(target,targetOwner,"PRIMEIRO ATO",(live,targetPlayer,next)=>{const reduced=Math.max(0,n-(hasKeyword(targetPlayer,live,"Robusto")?1:0));live.damage+=reduced;if(c.tags.some(tag=>cleanName(tag)==="roubo de vida"))next.players[owner].life=Math.min(30,next.players[owner].life+reduced);if(splash)targetPlayer.board.filter(unit=>Math.abs(unit.slot-live.slot)===1).forEach(unit=>{deferUnitImpact(unit,targetOwner,"IMPACTO ADJACENTE",adjacent=>{adjacent.damage+=Math.max(0,splash-(hasKeyword(targetPlayer,adjacent,"Robusto")?1:0))})});log(next,`${c.name} ativou Primeiro Ato: ${reduced} de dano em ${live.name}${splash?` e ${splash} nas criaturas adjacentes`:""}.`,"damage")})}else log(g,`${c.name} entrou em campo; Primeiro Ato não teve alvo para causar dano.`,"effect");resolved=true}
  const damageMatch=primaryText.match(/cause\s+(\d+)\s+de dano/);if(damageMatch&&!firstActDamage){const n=Number(damageMatch[1]),target=chosenEnemy||(!targetUid?o.board[0]:undefined);if(target){const targetOwner=(owner===0?1:0) as 0|1;deferUnitImpact(target,targetOwner,"EFEITO DE DANO",(live,targetPlayer,next)=>{const reduced=Math.max(0,n-(hasKeyword(targetPlayer,live,"Robusto")?1:0));live.damage+=reduced;if(c.tags.some(tag=>cleanName(tag)==="toque da morte")&&reduced>0&&!hasKeyword(targetPlayer,live,"Indestrutível"))live.damage=999;if(c.tags.some(tag=>cleanName(tag)==="roubo de vida"))next.players[owner].life=Math.min(30,next.players[owner].life+reduced);log(next,`${c.name} causou ${reduced} de dano em ${live.name}.`,"damage")})}else if(targetUid==="enemy-hero"||!o.board.length){o.life-=n;p.damageDealt+=n;if(c.tags.some(tag=>cleanName(tag)==="roubo de vida"))p.life=Math.min(30,p.life+n);log(g,`${c.name} causou ${n} de dano ao herói adversário.`,"damage")}resolved=true}
